            const hinaCard = document.getElementById('hina-card');
            const tsukiCard = document.getElementById('tsuki-card');
            let charactersPresent = 0;

            const worldDate = SafeGetValue(characterData, 'World_State.日期');
            const worldTime = SafeGetValue(characterData, 'World_State.时间');
